/**
 * Mirror an authored file tree onto a durable storage prefix. Shared by the
 * skills, workspace seed, and session workspaceFile syncs so they keep the
 * same write-then-sweep discipline and the same path refusals.
 */
import { posix } from "node:path";
import { FileConflictError } from "../files.js";
/**
 * Write every `desired` key, then delete keys under `prefix` (and the
 * `legacyPrefixes`) that nothing claims, so a redeploy drops removed files.
 * Writes land before stale deletes, so a failed sync never leaves a gap a
 * concurrent cloud reader could see.
 */
export async function mirrorToStore(args) {
    await Promise.all([...args.desired].map(([key, body]) => putLastWriterWins(args.sink, key, body)));
    const listed = await Promise.all([args.prefix, ...(args.legacyPrefixes ?? [])].map((prefix) => args.sink.list(prefix)));
    await Promise.all(listed
        .flat()
        .filter((entry) => !args.desired.has(entry.key))
        .map((entry) => args.sink.delete(entry.key)));
}
/**
 * Same refusals as local materialization's `resolveInside`: a rel that
 * escapes its directory or cannot round-trip through managed storage
 * (`..`, `.`, `//`, absolute) fails the sync, exactly as it fails a local
 * workspace write. Backslashes are refused because storage normalizes path
 * separators, which would change the desired key.
 */
export function storeRelPath(relPath, what) {
    if (relPath.includes("\0") ||
        relPath.includes("\\") ||
        posix.isAbsolute(relPath) ||
        relPath.endsWith("/") ||
        relPath.split("/").some((seg) => seg === ".." || seg === ".") ||
        posix.normalize(relPath) !== relPath) {
        throw new Error(`Refusing ${what} path "${relPath}" (must be a normalized relative path)`);
    }
    return relPath;
}
/**
 * Last writer wins. A raced conditional put clears the sink's cached etag,
 * so one retry re-learns the current version and lands.
 */
async function putLastWriterWins(sink, key, body) {
    try {
        await sink.put(key, body);
    }
    catch (error) {
        if (!(error instanceof FileConflictError)) {
            throw error;
        }
        await sink.put(key, body);
    }
}
